@Post('/orders')
async create(@Body() dto: CreateOrderDto) {
  const order = await this.orders.insert(dto)
  const payment = await this.payments.charge(dto.card, dto.total)
  await this.orders.markPaid(order.id, payment.id)
  await this.email.sendReceipt(dto.email, order.id)
  return order
}

async function handleBatch(messages: Message[]) {
  messages.forEach(async (message) => {
    const user = await users.get(message.userId)
    await billing.apply(message.invoiceId, user)
  })

  await queue.ack(messages)
}
